import pandas as pd

def friday_purchases(purchases: pd.DataFrame) -> pd.DataFrame:
    df = purchases.copy()
    df['purchase_date'] = pd.to_datetime(df['purchase_date'])
    df = df[(df['purchase_date'].dt.year == 2023) & (df['purchase_date'].dt.month == 11) & (df['purchase_date'].dt.dayofweek == 4)]
    if df.empty:
        return pd.DataFrame(columns=['week_of_month', 'purchase_date', 'total_amount'])
    grouped = df.groupby('purchase_date')['amount_spend'].sum().reset_index()
    start_week = pd.to_datetime('2023-11-01').isocalendar()[1]
    grouped['week_of_month'] = grouped['purchase_date'].dt.isocalendar().week - start_week + 1
    grouped = grouped.rename(columns={'amount_spend': 'total_amount'})
    grouped['purchase_date'] = grouped['purchase_date'].dt.strftime('%Y-%m-%d')
    return grouped[['week_of_month', 'purchase_date', 'total_amount']].sort_values(by='week_of_month')
